    body: "森田洋司（1941-2019）は、1980年代の国内外の実証研究に基づき、いじめを加害者と被害者の二者関係のみで捉えるのではなく、その周囲にいる子どもたちの存在も含めた集団的な現象として分析する「いじめの四層構造論」を提唱しました。\n\nこのモデルでは、いじめが起こる学級集団を、いじめを行う「加害者」、いじめを受ける「被害者」、面白がってはやし立てる「観衆」、見て見ぬふりをする「傍観者」の四つの層に分けて捉えます。観衆や傍観者の存在がいじめを助長・維持する力になる一方で、そこから仲裁者や通報者が増えることでいじめを抑止する力にもなり得ると考えられています。\n\nこの理論は、加害者・被害者だけに焦点を当てた指導では不十分であり、周囲にいる子どもたちの行動をいかに変えるかがいじめ防止の鍵であるという考え方につながり、「いじめ防止対策推進法」（2013年）に基づく生徒指導や道徳教育、学級づくりの実践に大きな影響を与えています。傍観者を「仲裁者」や「通報者」へと変えていく働きかけが、各学校のいじめ防止プログラムの柱の一つとされています。",
