    body: "多文化共生教育は、国籍、民族、言語、宗教などの異なる背景を持つ人々が、互いの文化的差異を認め合いながら対等な関係を築き、地域社会の構成員として共に生きていくことを目指す教育の考え方です。総務省は2006年に公表した「多文化共生の推進に関する研究会報告書」において、多文化共生を「国籍や民族などの異なる人々が、互いの文化的ちがいを認め合い、対等な関係を築こうとしながら、地域社会の構成員として共に生きていくこと」と定義しています。\n\n学校教育においては、日本語指導が必要な外国人児童生徒等の増加を背景に、異文化理解の学習や、外国につながる子どもへの日本語支援、偏見・ステレオタイプへの気づきを促す授業などが、道徳科や特別活動、総合的な学習の時間を通じて行われています。\n\nこの考え方は、単に異文化の知識を紹介する国際理解教育にとどまらず、身近な地域社会における多様性の受容と対等な関係づくりを重視する点に特徴があり、人権教育やシティズンシップ教育とも密接に関連しています。グローバル化が進む地域社会の中で共生の力を育む教育として、今後さらに重要性を増すと考えられています。",
