    summary:
      "戦争や暴力の歴史・構造を学び、平和を実現するための価値観や行動力を育てることを目的とする教育の総称。日本では広島・長崎の被爆体験や沖縄戦の記憶の継承などを中心に、戦後長く発展してきた。",
    body: "平和教育は、戦争や紛争、構造的な暴力について学び、平和的な社会を築くための知識・態度・行動力を育成することを目的とする教育活動の総称です。日本においては、広島・長崎への原子爆弾投下や沖縄戦など、第二次世界大戦の惨禍を次世代に継承し、二度と戦争を繰り返さないという誓いを込めた実践が中心的な位置を占めてきました。\n\nノルウェーの平和学者ヨハン・ガルトゥングは、戦争や直接的な暴力行為が存在しない状態を「消極的平和」、貧困や差別といった構造的な暴力までもが存在しない状態を「積極的平和」と区別しました。この考え方は、単に戦争を防ぐだけでなく社会の不公正にも目を向ける、平和教育の目標を広げる理論的基盤となっています。\n\n学校教育では、社会科や道徳科、総合的な学習の時間などを通じて、戦争体験者からの聞き取りや平和資料館の見学、国際紛争や人権問題についての学習が行われています。生命の尊さや他者への共感を育む道徳教育とも密接に関わり、持続可能な開発のための教育（ESD）の重要な柱の一つにも位置づけられています。近年は国際紛争や難民問題など、現代的な課題を扱う教材開発も進められています。",
