    body: "いのちの教育（生命尊重の教育）は、動植物の飼育・栽培体験や、誕生・死をめぐる話し合い、闘病体験者・被災者の講話などを通して、生命が一つしかなくかけがえのないものであること、そして生命が多くの支えやつながりの中で育まれていることへの気づきを促す教育です。\n\n学習指導要領における道徳科の内容項目「生命の尊さ」では、生命の連続性や有限性、そして生命がかけがえのないものであることを実感することを通して、自他の生命を尊重する心を育てることが求められています。背景には、いじめによる自殺や重大な少年事件など、生命軽視が疑われる社会問題への強い危機感があり、1990年代以降、各地の教育委員会や学校で重点的な取組として広がってきました。\n\n具体的な実践としては、助産師や医師を招いた「いのちの授業」、動物の出産や死を扱う教材、大災害の被災地との交流学習などがあり、道徳科だけでなく特別活動や総合的な学習の時間とも連携しながら、学校の教育活動全体を通じて行われています。命の大切さを頭で理解するだけでなく、実感を伴って捉えられるようにする点が重視されています。",
