    body: "公共の精神とは、社会生活を営むうえで必要な規範を守り、自分と社会との関わりを自覚しながら、公共の利益や社会全体の発展のために主体的に貢献しようとする態度を指す言葉です。2006年に全面改正された教育基本法第2条（教育の目標）には「公共の精神に基づき、主体的に社会の形成に参画し、その発展に寄与する態度を養うこと」が教育の目標の一つとして新たに明記されました。\n\n学習指導要領の道徳科においても、中学校の内容項目「社会参画、公共の精神」として、社会参画の意識と社会連帯の自覚を高め、公共の精神をもって地域社会の発展に努める態度を養うことが示されています。単なる規則遵守にとどまらず、身近な集団や地域社会の課題を自分事として捉え、主体的に関わろうとする姿勢が重視されている点が特徴です。\n\nこの考え方は、シティズンシップ教育や主権者教育、ボランティア活動、特別活動における児童会・生徒会活動などとも密接に関連しながら、学校の教育活動全体を通じて育成が図られています。2015年の選挙権年齢の引き下げ以降、主権者教育の文脈で語られる機会も増えています。",
