    body: "「心のノート」は、文部科学省が2002年（平成14年）4月から全国の小・中学校の全児童生徒に無償配布した道徳教育の副教材です。児童生徒が道徳的価値や自己の生き方について自分自身で考え、書き込みながら振り返ることができるよう工夫されており、小学校低学年・中学年・高学年用、中学校用と、学年段階に応じた4種類の冊子として作成されました。\n\n2009年には新学習指導要領への対応として内容の一部改訂が行われ、2013年3月には教師用の指導手引き書も改訂されるなど、活用を後押しする取組が続けられました。さらに2013年12月には全面改訂が行われ、「私たちの道徳」（小学校低・中学年は「わたしたちの道徳」）へと名称を変更し、翌2014年度から全国の学校に配布されました。\n\nその後、2015年の学習指導要領一部改正により「特別の教科 道徳」が新設され、検定教科書が用いられるようになったことに伴い、副教材としての役割は教科書に引き継がれる形で移行しました。心のノート・私たちの道徳は、教科化以前の日本の道徳教育を長く支えた代表的な教材として位置づけられています。",
