    title: "ピアジェの道徳性発達理論",
    reading: "ぴあじぇのどうとくせいはったつりろん",
    kana: "ひ",
    categories: ["moral", "psychology"],
    summary:
      "スイスの心理学者ジャン・ピアジェが提唱した、子どもの道徳判断が大人への服従を基盤とする「他律的道徳性」から、仲間との合意に基づく「自律的道徳性」へと発達していくとする理論。コールバーグ理論の源流となった。",
    body: "ジャン・ピアジェ（1896-1980）は、著書『児童の道徳判断』（1932年）において、子どもたちが規則やルールをどのように理解し、行為の善悪をどのように判断するかについての発達的な変化を、おはじき遊びの観察や面接調査を通じて明らかにしました。\n\nピアジェによれば、幼い子どもは、規則を大人や神など権威ある存在が定めた絶対に変更できないものと捉え、行為の意図よりもその結果の大きさによって善悪を判断する「他律的道徳性」の段階にあります。その後、おおむね8〜10歳頃を境に、規則は仲間との合意によって変更しうる約束事であると理解するようになり、結果よりも行為の背後にある意図を重視して判断する「自律的道徳性」の段階へと移行するとされます。\n\nこの理論は、子ども同士の協同的な遊びやルールづくりの経験そのものが道徳性の発達を促すという知見を示すとともに、コールバーグの道徳性発達理論の直接の源流となり、その後の道徳心理学研究全体に大きな影響を与えました。教師による一方的な訓育よりも、仲間との対等な相互作用を重視する視点は、今日の道徳教育にも通じています。",
    relatedSlugs: ["kohlberg", "ninchi-hattatsu", "selman-shiten-shutoku"],
    isCanonical: true,
    tags: ["ピアジェ", "他律から自律へ", "児童の道徳判断"],
