    body: "ロバート・セルマンは、他者の考えや気持ちを自分とは異なる視点から理解する能力を「役割取得能力（視点取得能力）」と呼び、これが子どもの発達に伴って段階的に高まっていくことを示しました。ピアジェやコールバーグの理論と並んで、社会的認知や道徳性の発達を説明する代表的な理論の一つとして位置づけられています。\n\nセルマンの発達段階は、自分と他者の視点の違いをうまく区別できないレベル0（自己中心的役割取得、おおむね3〜5歳）から始まり、自分と他者の視点は区別できても両者を関連づけて考えることが難しいレベル1（主観的役割取得、6〜7歳）、他者の視点から自分自身の考えや行動を振り返って捉えられるレベル2（二人称相応的役割取得、8〜11歳）などを経て、やがて社会全体や第三者の視点から物事を捉えられる段階へと進むとされます。\n\nこの理論は、他者の立場に立って考える力が、思いやりや道徳的な判断の基盤になるという考え方を裏づけるものであり、道徳教育や特別活動における人間関係づくりの実践、いじめ防止教育の理論的背景としても幅広く参照されています。",
