      "教育カウンセラーの國分康孝が日本の学校教育に合わせて体系化した、簡単な課題（エクササイズ）とその振り返り（シェアリング）を通して、人間関係づくりと自己発見を促す集団体験学習の技法。",
    body: "構成的グループエンカウンター（SGE：Structured Group Encounter）は、教育カウンセラーの國分康孝（1930-2018）が1970年代後半に体系化した、学校現場でも扱いやすいグループワークの手法です。アメリカ発祥の自由度の高いエンカウンター・グループを日本の学校に導入する際、感情表出が過剰になる弊害を避けるため、ねらいや進め方をあらかじめ決めた「構成的」な枠組みを設けた点に大きな特徴があります。\n\n実践では、リーダー役の教師が提示する簡単な課題（エクササイズ）にグループで取り組み、その体験を通して感じたことや気づいたことを互いに率直に語り合う「シェアリング」を行います。これにより、他者との「ふれあい（リレーション）」を深めるとともに、自分自身についての新たな気づき（自己発見）を得ることをねらいとしています。\n\nいじめの未然防止や学級集団づくり、道徳科・特別活動の時間を活用した人間関係プログラムとして、日本の多くの小・中・高等学校で導入されており、予防的・開発的カウンセリングを代表する技法の一つとして位置づけられています。",
