    summary:
      "違反や対立を罰することよりも、当事者間の対話を通じて関係の修復と問題の解決を図ろうとする考え方。近年、欧米の学校を中心に、いじめや校内トラブルへの対応方法として教育現場にも導入され始めている。",
    body: "修復的正義（Restorative Justice）は、もともと刑事司法の分野で発展した考え方で、犯罪や違反行為を「規則を破った者への処罰」としてのみ捉えるのではなく、被害者・加害者・関係する地域社会の人々がともに対話し、関係の修復と問題解決を図ることを重視する立場です。上から一方的に下す制裁ではなく、当事者自身の自律性と対話による解決力を尊重する点に大きな特徴があります。\n\n学校教育においては、いじめや暴力行為、対人トラブルが起きた際に、加害・被害の両当事者やその関係者が訓練を受けたファシリテーターの進行のもとで対話を行い、何が起きたのか、どのような影響があったのか、そしてどうすれば関係を修復できるのかを話し合う「修復的対話」の実践として広がりつつあります。\n\n欧米の学校では生徒指導の一つの柱として定着しつつある一方、日本ではまだ用語自体の認知度は高くありませんが、NPOによる対話実践や大学等での研究が2000年代以降着実に蓄積されており、懲戒中心の生徒指導を補完・転換する視点として近年注目を集めています。",
