    body: "修身は、1880年（明治13年）の改正教育令によって小学校の筆頭教科に位置づけられた、道徳教育を目的とする教科です。1890年（明治23年）に教育勅語が発布され、忠君愛国と儒教的な家族道徳を基調とする国民道徳の基準が示されると、翌1891年に公布された「小学校教則大綱」では、修身の内容が教育勅語の趣旨に基づくべきことが明記され、以後、国定教科書によって全国の学校で画一的に教えられるようになりました。\n\n修身の授業では、忠孝・勤勉・順法といった徳目を、偉人の逸話や物語を通じて教え込む方法が中心となり、教育勅語の理念を体現する国民の育成を目的とする性格が次第に強まっていきました。\n\n第二次世界大戦後、GHQ（連合国軍最高司令官総司令部）は1945年12月、修身・日本歴史・地理の授業停止を指令し、教育勅語も1948年に国会で排除・失効確認の決議がなされたことで、修身は教科として正式に廃止されました。この経緯は、戦後長らく学校における道徳教育のあり方を慎重にする要因となり、1958年の「道徳の時間」新設や2015年の道徳科教科化をめぐる議論の重要な歴史的背景となっています。",
