    body: "道徳性の三様相とは、日本の学習指導要領および道徳科の解説において、道徳性を構成する諸様相として示される「道徳的判断力」「道徳的心情」「道徳的実践意欲と態度」の三つを指す言葉です。道徳的な行為を支える心の働きを分析的に捉えるための枠組みとして、長く道徳教育論の基本に位置づけられてきました。\n\n道徳的判断力は、それぞれの場面において善悪を判断する能力であり、様々な状況の中で人間としてどのように対処することが望ましいかを見極める力とされます。道徳的心情は、道徳的価値の大切さを感じ取り、善を行うことを喜び、悪を憎む感情を指します。道徳的実践意欲と態度は、判断力や心情を基盤として道徳的価値を実現しようとする意志の働き、およびそれに裏づけられた具体的な行為への身構えを意味します。\n\nこれら三つの様相は互いに独立したものではなく、密接に関連し合い、統合的に働くことで道徳的な実践行為（行動）へとつながっていくと説明されます。この枠組みは、道徳科の学習指導案作成や、数値ではなく記述によって行う道徳科の学習状況の評価を行う際の基本的な考え方としても用いられています。",
