    body: "「考え、議論する道徳」への転換は、2015年（平成27年）の学習指導要領一部改正による「特別の教科 道徳」の新設を機に打ち出された、道徳授業の質的改善を目指すスローガンです。背景には、2014年10月の中央教育審議会答申「道徳に係る教育課程の改善等について」があり、いじめ問題への対応の必要性や、従来の道徳授業が読み物教材の登場人物の心情を読み取らせるだけの、いわゆる「読み物道徳」に偏りがちであったという課題が指摘されました。\n\nこの改革では、正解が一つに定まらない道徳的な課題を児童生徒自身の「自分事」として捉え、多面的・多角的な視点から考え、他者との対話や議論を通じてより良い生き方を追求していく学習への転換が求められました。文部科学省の教育課程部会には「道徳教育に係る教育課程の改善等に関する専門部会」の下に「考える道徳への転換に向けたワーキンググループ」が置かれ、具体的な授業のあり方についての検討が進められました。\n\nこの方針は、問題解決的な学習やモラルジレンマ授業、体験的な学習の一層の充実を求めるものであり、検定教科書の使用や評価の導入と合わせて、今日の道徳科の授業づくり全体を貫く基本方針となっています。",
