    body: "戦後の日本では、修身科の廃止後、道徳教育は特定の教科としてではなく、学校の教育活動全体を通じて行うという「全面主義」の原則が新たに採用されました。しかし学校現場では、特定の教科という形をとらないために道徳教育が実質的に軽視されがちであるとの指摘が高まり、独立した指導の時間を設けるべきだとする「特設主義」の主張が次第に強まっていきました。\n\n1957年（昭和32年）の教育課程審議会答申を経て、1958年（昭和33年）の学習指導要領改訂により、「道徳の時間」が小・中学校の教育課程に週1時間設けられることになりました。これは全面主義の原則を維持しつつ特設の時間も組み合わせるものとされましたが、道徳教育の政治的な位置づけをめぐる賛否も絡み、単純な「道徳教育への賛否」という形で論争が展開された面もありました。\n\nこの論争は、その後長く続く「道徳の時間」の位置づけをめぐる議論の出発点となり、2015年の学習指導要領一部改正による「特別の教科 道徳」への移行に至るまで、日本の道徳教育のあり方を考えるうえでの重要な歴史的論点であり続けています。",
