    body: "ジャストコミュニティ（Just Community）は、道徳性発達理論の提唱者であるローレンス・コールバーグが、1970年代に自らのモラルジレンマ討論の実践を批判的に検討する中から生み出した学校改革プログラムです。コールバーグは、仮想的な事例についての討論だけでは、判断力の発達が実際の日常的な道徳的行動に必ずしも結びつきにくいという「理論と実践の乖離」を課題と捉え、その克服を目指しました。\n\nジャストコミュニティでは、学校（学級）そのものを一つの民主的な共同体として運営し、校則や日常生活上のルールづくり、生活上のトラブルへの対応などを、教師と生徒が対等な立場で話し合う全体集会を通じて決定していきます。生徒は、実際の学校生活の中で日々生じる具体的な道徳的問題について、責任をもって議論し合意形成に参加するという経験を積み重ねることになります。\n\nアメリカのスカースデール・オルタナティブスクールなどでの実践がよく知られており、道徳的な討論の対象を仮想事例から現実の学校生活の場へと広げ、共同体への主体的な参加を通じて道徳性を育てようとする点で、モラルジレンマ授業を補完する取組として位置づけられています。",
