    body: "徳倫理学とは、ある行為が正しいかどうかを、行為そのもののルールや結果ではなく、その行為をなす人がどのような徳（アレテー）を備えているかという観点から捉える倫理学の立場です。アリストテレスの『ニコマコス倫理学』を源流とし、義務論や功利主義と並ぶ規範倫理学の主要な立場の一つとされています。\n\n徳倫理学では、勇気・誠実・思いやりといった徳は、繰り返しの実践と習慣づけによって身につく性格特性であると考えられます。ルールの暗記や損得計算ではなく、望ましい行動を反復することで人格そのものを陶冶していくという発想は、道徳教育における「習慣化」や「体験的な学び」の重視と強く結びついています。\n\n1980年代以降の欧米における人格教育（character education）運動は、徳倫理学の考え方を理論的な支柱の一つとしており、日本の道徳教育でも、規範の理解にとどまらず、望ましい行動を実際に経験し積み重ねることの意義が重視されている点に、その影響を見ることができます。",
