    body: "キャロル・ギリガンは、1982年の著書『もうひとつの声（In a Different Voice）』の中で、師であったコールバーグの道徳性発達段階理論が、正義や権利といった原理を重視する立場に偏っており、女性に見られやすい人間関係や配慮を重んじる道徳的な語り口を十分にすくい取れていないと批判しました。\n\nギリガンは、権利や公正さを基準とする「正義の倫理」に対して、他者との関係性や具体的な状況の中での配慮を基準とする「ケアの倫理」という、もう一つの道徳的な声があることを示しました。これは、抽象的なジレンマに対する論理的な判断力を測るコールバーグの方法論自体への異議申し立てでもありました。\n\nこの提起は、その後のケアリング理論（ノディングズら）や、道徳性発達研究における性差をめぐる論争を大きく活性化させ、正義とケアという二つの視点をどう統合的に理解するかという課題は、現在の道徳教育論においても重要な論点であり続けています。",
