    body: "道徳的想像力とは、自分の目の前にない他者の状況や、自分の行為が将来もたらす帰結を思い描き、そこに配慮を働かせながら判断や行動を選び取る認知的な働きのことです。哲学者ジョン・デューイや、それを発展させたマーク・ジョンソンらの議論を通じて、規則の機械的な適用とは異なる道徳的思考のあり方として注目されてきました。\n\n道徳的想像力は、単一の正解が想定しにくい複雑な状況において特に重要になります。ある行為が誰にどのような影響を与えるかを多面的に想像することは、道徳科の授業における「多面的・多角的に考える」学びの土台となる力だと位置づけられます。\n\n物語教材の登場人物の心情を追体験したり、役割演技を通じて他者の視点に立ったりする活動は、道徳的想像力を育てる代表的な指導方法とされ、共感性や他者理解の発達とも密接に関わっています。",
