    body: "モラルスキルトレーニングとは、道徳的な価値についての理解や判断力を育てるだけでなく、実際の対人場面で望ましい行動を選び、うまく実行するための具体的なスキルの獲得を目指す指導の技法です。道徳的判断が必ずしも道徳的行動に直結しないという指摘を背景に、社会的スキルトレーニング（SST）の考え方を道徳教育に取り入れたものとして発展してきました。\n\n具体的には、あいさつの仕方、謝り方、断り方、意見の異なる相手との折り合いのつけ方といった場面を取り上げ、モデリング、リハーサル（練習）、フィードバックといった手順を通じて、望ましい行動のレパートリーを段階的に身につけさせていきます。\n\n知識として「なぜそれが大切か」を理解する道徳的判断力の育成と、実際に「どうすればできるか」というスキルの獲得は互いに補い合う関係にあり、両者を組み合わせることで、学んだ価値観を日常生活の具体的な行動へとつなげやすくなると考えられています。",
