    body: "良心の発達とは、当初は保護者など周囲の大人から与えられていた「してはいけないこと」というルールが、子ども自身の内面に取り込まれ、大人が見ていない場面でも自分でルールに従おうとする内的な基準（良心）へと変わっていく過程を指します。発達心理学者グラジナ・コチャンスカらの研究が代表的です。\n\nコチャンスカらの縦断研究では、幼児期に見られる「してはいけないことをした後にためらう、悪びれる」といった様子から良心の芽生えを捉え、養育者との温かい愛着関係の中で、罰への恐れよりも、養育者を悲しませたくないという気持ちに基づいてルールを内面化していく子どもほど、良心が健全に発達しやすいことが示されています。\n\nこの理論は、外的な統制（叱責や罰）に頼る指導だけでは規範意識の内面化が進みにくいことを示唆しており、信頼関係に基づく温かい関わりの中で規範を伝えていくことの重要性を、幼児教育や道徳教育に対して示すものとなっています。",
