    body: "正義とケアの論争とは、コールバーグが体系化した、公正さや権利といった普遍的な原理に基づく「正義の倫理」と、ギリガンが提起した、具体的な関係性の中での配慮を重んじる「ケアの倫理」のどちらを道徳性の中心に据えるべきかをめぐって、1980年代以降展開されてきた理論的な論争です。\n\n論争の過程では、正義とケアが男女で異なる道徳性を表すものだとする性差の観点が注目を集めましたが、その後のローレンス・ウォーカーらによる実証研究では、道徳的推論の性差は当初考えられていたほど明確ではなく、多くの人が場面に応じて正義とケアの両方の視点を用いていることが示されています。\n\n現在では、正義とケアを対立させるのではなく、公正なルールの適用と、目の前の相手への配慮という二つの視点を状況に応じて統合的に働かせることこそが、成熟した道徳性のあり方だとする理解が広がっており、道徳教育の内容項目にも両方の視点が組み込まれています。",
