    body: "内容項目は、学習指導要領第3章「特別の教科 道徳」において、道徳科で扱う具体的な指導内容を体系立てて示したものである。小学校低学年（第1・2学年）で19項目、中学年（第3・4学年）で20項目、高学年（第5・6学年）と中学校でそれぞれ22項目が設定されており、発達段階に応じて内容が徐々に深まり広がるよう構成されている。各項目は「善悪の判断、自律、自由と責任」「友情、信頼」「郷土の伝統と文化の尊重、郷土を愛する態度」「生命の尊さ」など、具体的な道徳的価値を短いキーワードで表している。\n\n内容項目は4つの視点に分類される。Aは節度・節制、向上心、個性の伸長など主に自分自身に関わる価値、Bは親切・思いやり、感謝、礼儀、友情、相互理解など人との関わりに関する価値、Cは規則の尊重、公正・公平、勤労、家族愛、郷土愛、国際理解など集団や社会との関わりに関する価値、Dは生命の尊さ、自然愛護、感動・畏敬の念など生命や自然、崇高なものとの関わりに関する価値を扱う。これらは相互に関連し合っており、一つの授業で複数の内容項目にまたがる指導が行われることも多い。\n\n2015年の学習指導要領一部改正により「道徳の時間」が「特別の教科 道徳」として教科化された際、内容項目もキーワードが整理・統一され、各学校が作成する「全体計画」や「別葉」において、各教科等の指導内容と内容項目との関連を明示することが求められるようになった。教科書会社は内容項目ごとに教材を配列し、教師は年間指導計画の中で全ての内容項目を確実に指導することが求められている。",
