    body: "道徳教育の全体計画は、学校教育法施行規則および学習指導要領総則の規定に基づき、各学校が道徳教育を計画的・組織的に進めるために作成する基本文書である。学校の教育目標や実態、地域の特色などを踏まえた道徳教育の重点目標、道徳科の指導方針、各教科・総合的な学習の時間・特別活動など教育活動全体における道徳教育の位置付け、家庭や地域社会との連携の方針などが盛り込まれる。作成主体は校長であるが、実務は道徳教育推進教師が中心となり、全教職員の共通理解のもとで練り上げられる。\n\n道徳は道徳科の授業だけで完結するものではなく、学校の教育活動全体を通じて行うという「全教育活動を通じた道徳教育」の考え方が、全体計画には色濃く反映される。そのため、各教科等がどの時期にどの内容項目と関連する指導を行うかを一覧化した「別葉」を付随資料として作成し、教科横断的な道徳性の育成を可視化する学校が多い。全体計画は年度当初に教職員会議等で共通理解を図り、年度末には実施状況を評価して次年度の計画に反映させるという、PDCAサイクルの中に位置付けられる。\n\n2015年の教科化以降、全体計画の作成・活用は一層重視されるようになり、文部科学省や教育委員会は作成の手引きやシート様式を提供している。全体計画が形骸化し「作って終わり」にならないよう、日々の授業や学校行事との有機的な関連付け、道徳教育推進教師を中心とした校内研修の充実が課題として指摘されている。",
