    body: "別葉とは、道徳教育の全体計画を補足する資料として作成される一覧表であり、各教科、外国語活動、総合的な学習の時間、特別活動など学校の教育活動全体において、いつ、どの教科等で、どの道徳の内容項目に関わる指導が行われるかを可視化したものである。全体計画そのものに全ての情報を書き込むと文書が煩雑になるため、詳細な関連付けを別紙（別の葉）として整理することから「別葉」と呼ばれる。\n\n別葉を作成する意義は、道徳科の授業だけでなく学校の教育活動全体を通じて道徳性を養うという考え方を、教職員が具体的に共通理解できる形にする点にある。例えば国語科の物語教材で「思いやり」に触れる場面や、社会科で「郷土愛」に関わる学習を行う時期などを一覧化することで、道徳科の授業とその他の教育活動との重なりや補完関係を意識した指導が可能になる。教科書発行者の多くが、道徳教科書に対応した別葉の作成支援シートやひな形をウェブサイト等で提供しており、学校はこれを活用して自校の教育課程に合わせた別葉を作成することが一般的である。\n\n一方で、別葉の作成が形式的な一覧表作りに終始し、実際の授業改善に結び付いていないという課題も指摘される。別葉を活用して各教科担当教師が道徳的価値への意識を高め、教科指導の中で道徳性の育成を意図的に行うことが本来の目的であり、単なる文書整備にとどまらない運用が求められている。",
