    body: "読み物教材とは、登場人物が道徳的な問題や葛藤に直面する物語や、偉人の生き方を描いた伝記などの形式で構成された、道徳科授業の中心的な教材である。教師が読み聞かせたり児童生徒が音読・黙読したりした後、登場人物の心情や行動の理由を問う発問を通じて、教材に含まれる道徳的価値について考えさせる指導方法が長らく主流であった。戦後の道徳の時間創設以来、副読本や文部省（文部科学省）発行の資料集を中心に数多くの読み物教材が用いられてきた。\n\n従来型の読み物教材を用いた授業は、登場人物の気持ちを「主人公の気持ちを考えましょう」という形で一方向的に読み取らせ、教師が想定する「望ましい」結論に児童生徒を誘導しがちであることから、「読み取り道徳」あるいは「心情理解道徳」として批判されることがあった。こうした批判を踏まえ、教科化後の「考え、議論する道徳」への転換では、読み物教材を単なる感想文の題材としてではなく、複数の価値観の対立や葛藤を含む教材として活用し、児童生徒が多面的・多角的に考え議論する授業づくりが求められるようになった。\n\n現在の検定教科書には、伝記や物語形式の読み物教材に加えて、写真や図表を用いた資料、体験活動を促すワークシートなど多様な教材形態が併用されている。それでも読み物教材は道徳科教材の中核をなしており、教材の内容項目との対応や発問の工夫、登場人物への共感にとどまらない多角的な議論の設計が、授業づくりの重要な課題となっている。",
