    reading: "はいんつのじれんま",
    kana: "は",
    categories: ["moral", "psychology"],
    summary:
      "コールバーグが道徳性発達段階を測定するために用いた代表的なモラルジレンマ課題。がんの妻の薬を買う金がない夫ハインツが薬を盗むべきか否かを問う架空の物語で、応答の内容より判断の理由づけの構造を分析する。",
    body: "ハインツのジレンマは、ローレンス・コールバーグが道徳性発達段階の研究で用いた代表的なモラルジレンマ課題である。物語の概要は、妻ががんで死にかけているが、治療に必要な薬は薬剤師が法外な高値をつけており、夫のハインツは必要な金額を工面できない。あらゆる手段を尽くしても足りず、ハインツは薬を盗むべきかどうか、という架空の状況を提示し、「ハインツは薬を盗むべきか」「なぜそう考えるか」を尋ねる。\n\nコールバーグの分析で重要なのは、「盗むべき」「盗むべきでない」という結論そのものではなく、その結論に至る理由づけの構造である。例えば「捕まって罰せられるから盗むべきでない」という回答は前慣習的水準の理由づけであり、「夫婦の愛情や生命の尊さを優先すべきだから盗むべき」という回答はより高次の水準の理由づけとみなされる。この手法により、コールバーグは道徳的判断の発達を前慣習的水準・慣習的水準・脱慣習的水準の3水準6段階として体系化した。\n\nハインツのジレンマは日本の道徳教育においても、モラルジレンマ授業や「考え、議論する道徳」の教材開発の基礎となる代表事例として紹介されることが多い。一方で、架空の極端な状況設定であることや、女性の道徳的推論を過小評価しているというギリガンらの批判の対象にもなった。それでも、単一の正解を教え込むのではなく、対立する価値の間で理由づけを深める道徳授業のモデルとして、今日でも教員養成課程や道徳教育研究で頻繁に取り上げられている。",
    relatedSlugs: ["kohlberg", "moral-dilemma", "gilligan-care-ethics", "kangae-giron-dotoku"],
    isCanonical: true,
