    categories: ["moral", "psychology"],
    summary:
      "心理学者ジェームズ・レストが提唱した、道徳的行動が成立するために必要な4つの心理過程からなるモデル。道徳的感受性・道徳的判断・道徳的動機づけ・道徳的実行力の4要素から構成される。",
    body: "ジェームズ・レストは、コールバーグの弟子筋にあたるミネソタ大学の心理学者で、道徳的判断力の発達だけでは道徳的行動の全体を説明できないという問題意識から、道徳的行動が成立するまでに必要な4つの心理過程を示す「四要素モデル（Four Component Model）」を提唱した。この4要素は、道徳的行動に至る段階的な手順ではなく、相互に影響し合いながら道徳的行動を生み出す並行的な心理過程として位置付けられている。\n\n第一の要素「道徳的感受性」は、ある状況に道徳的な問題が含まれていることに気付き、自分の行動が他者にどのような影響を与えるかを認識する能力である。第二の要素「道徳的判断」は、その状況において何が道徳的に正しい行為であるかを判断する能力であり、コールバーグの道徳性発達段階論が主に扱ってきた領域にあたる。第三の要素「道徳的動機づけ」は、他の欲求や価値よりも道徳的な価値を優先し、正しいと判断した行為を実行しようとする意志の強さである。第四の要素「道徳的実行力」は、判断し動機づけられた行為を、様々な障害や誘惑に打ち勝って実際にやり遂げる実行力や強い意志を指す。\n\nレストは、道徳的に望ましくない行動は、これら4要素のいずれか一つの欠如だけでなく、複数の要素の組み合わせの失敗によって生じうると論じた。このモデルは、単に「正しい判断ができる」ことと「実際に正しく行動できる」ことの間にあるギャップを説明する枠組みとして、道徳教育や専門職倫理教育の研究で広く用いられている。",
    relatedSlugs: ["kohlberg", "moral-skill-training", "dotokusei-sanyoso", "ryoshin-hattatsu"],
    isCanonical: true,
    tags: ["レスト", "四要素モデル", "道徳的行動"],
