    body: "功利主義は、18〜19世紀のイギリスでジェレミー・ベンサムとジョン・スチュアート・ミルによって体系化された倫理思想であり、ある行為の道徳的な善悪を、その行為がもたらす結果としての幸福や快楽の総量によって判断する帰結主義の代表的立場である。ベンサムは「最大多数の最大幸福」を道徳と立法の原理とし、快楽と苦痛を量的に計算できるものとして扱う「快楽計算」を提唱した。ミルはこれを継承しつつ、快楽には質的な差異があるとして、精神的な快楽を身体的な快楽より高く位置付ける「質的功利主義」を展開した。\n\n功利主義は、行為そのものの性質や動機ではなく、その結果として社会全体にもたらされる幸福の総量を重視する点で、行為の動機や義務そのものの正しさを重視するカントの義務論としばしば対比される。道徳教育の文脈では、政策決定や資源配分など「多数の利益のために少数が犠牲になってよいか」といった価値の対立を扱う教材において、功利主義的な考え方と義務論的な考え方を対比させることで、児童生徒に多面的・多角的な思考を促す枠組みとして活用される。\n\n一方で功利主義には、個人の権利や尊厳が「全体の幸福」の名の下に軽視されかねないという批判が古くから存在する。道徳科の授業においても、功利主義的な発想だけで結論を出すことの危うさに触れつつ、義務論やケアの倫理など複数の倫理的立場を比較検討させることが、単純な二項対立に陥らない道徳的判断力の育成につながるとされている。",
