    body: "義務論は、行為の道徳的な正しさを、その行為がもたらす結果の善さではなく、行為そのものが普遍的な道徳法則や義務に合致しているかどうかによって判断する倫理学の立場である。代表的な論者であるイマヌエル・カントは、行為の動機が「義務のために義務を果たそうとする善意志」に基づいているかを重視し、「あなたの意志の格率が、常に同時に普遍的立法の原理として妥当しうるように行為せよ」という定言命法を道徳法則の基準として示した。カントはまた、人間を単なる手段としてではなく、常に同時に目的として扱わなければならないという「人格の尊厳」の考え方も提示している。\n\n義務論は、結果の善し悪しにかかわらず「やってはいけないことはやってはいけない」という立場をとる点で、結果の総量を重視する功利主義と鋭く対比される。例えば「少数の犠牲によって多数が救われる」状況において、功利主義は結果として多数が助かることを支持しうるのに対し、義務論は結果にかかわらず人を手段として犠牲にする行為そのものを否定しうる。この対比は、トロッコ問題のような思考実験を通じて倫理学教育でしばしば用いられる。\n\n日本の道徳科においても、規則の尊重や公正・公平などの内容項目を扱う際、「なぜそれが正しいのか」を結果からではなく行為や規則そのものの普遍性から考えさせる視点として、義務論的な発想が背景にある教材が少なくない。功利主義や徳倫理学など他の倫理的立場と併せて紹介することで、単一の価値観に偏らない多面的・多角的な道徳的判断力の育成が図られている。",
