    body: "徳育とは、知育・体育と並ぶ教育の三領域（三育）の一つとして、人の徳性・道徳性を養うことを目的とする教育を指す語である。この三育の考え方は、19世紀イギリスの哲学者ハーバート・スペンサーの教育思想などに由来するとされ、明治期に日本に紹介されて以降、近代日本の教育制度における人格形成の理念的な柱として位置付けられてきた。\n\n近代日本の学校制度においては、徳育を担う教科として1880年代以降「修身」が筆頭教科として位置付けられ、教育勅語に示された忠君愛国・忠孝などの徳目を中心とした国家主義的な徳育が展開された。戦後、修身は軍国主義的教育への反省から1945年に停止され、1958年には教科ではない「道徳の時間」が新設された。2015年の学習指導要領一部改正により「特別の教科 道徳」として教科化されるまで、日本の学校における徳育は長らく教科外の教育活動として位置付けられてきた。\n\n「徳育」という語自体は、現在では「道徳教育」という語に置き換えられることが多いが、教育史や教育思想史の文脈では、知育偏重批判との対比で人格形成・情操教育の重要性を論じる際に、今なお用いられる基本概念である。徳育・知育・体育の均衡のとれた発達を目指す「全人教育」の理念とも密接に結び付いている。",
