    body: "品格教育（Character Education）は、アメリカ合衆国において1990年代以降に急速に広まった学校教育改革運動であり、信頼性（trustworthiness）・尊重（respect）・責任（responsibility）・公正（fairness）・思いやり（caring）・市民性（citizenship）などの中核的な価値・徳目を、学校教育を通じて明示的に教え、日々の習慣として定着させることを目指すものである。1993年には全米規模の推進団体であるキャラクター・エデュケーション・パートナーシップが設立され、1994年には連邦議会が「品格教育のためのパートナーシップ・プログラム」を予算措置するなど、政策的にも後押しされた。\n\n背景には、青少年の非行や暴力、薬物乱用などをめぐる社会的な危機意識があり、価値観の押し付けを避けようとした1960〜70年代の「価値の明確化（バリュー・クラリフィケーション）」の反省から、特定の望ましい価値・徳目を積極的に教え込むべきだとする立場への揺り戻しという側面もあった。トーマス・リコーナら心理学者は、品格を「道徳的な知る力」「道徳的な感じる力」「道徳的な行う力」の統合として捉え、学校全体の文化として徳目を実践させる「包括的アプローチ」を提唱した。\n\n代表的な実践プログラムには、キャラクター・カウンツ！（六つの柱を掲げるプログラム）やハートウッド・プログラムなどがあり、学校の規則・儀式・教科指導・課外活動など学校生活全体を通じて品格を涵養する点が特徴である。日本の道徳科が内容項目という体系立てた価値の一覧を提示する点は、アメリカの品格教育における中核的価値のリストと構造的に類似しており、両者は比較教育学の観点からしばしば対比・参照される。",
