    summary:
      "道徳科の内容項目Dの一つで、生命が唯一無二でかけがえのないものであることを理解し、自他の生命を尊重する態度を育てることを目的とする。自殺予防教育や生命倫理教育とも関連の深い内容項目。",
    body: "「生命の尊さ」は、道徳科の内容項目における視点D「主として生命や自然、崇高なものとの関わりに関すること」に位置付けられる内容項目の一つであり、生命が有限でかけがえのないものであることを理解し、自他の生命を尊重する心情や態度を育むことを目標とする。学習指導要領解説では、生命の連続性や有限性、心身の健康、自然界における生命の連鎖など、様々な角度から生命の尊さについて考えさせることが求められている。\n\nこの内容項目は、発達段階に応じて扱う視点が広がっていく構成になっている。小学校低学年では身近な動植物や自分自身の体験を通じて生命の大切さを感じ取らせることから始まり、学年が上がるにつれて、生命が多くの人々の支えの中で存在していることや、生命の連続性・有限性についての理解、さらには自らの死生観に関わる思索へと発展していく。中学校段階では、生命の尊厳という抽象的な概念について、宗教的・哲学的な視点も交えながら考えさせる教材も用いられる。\n\n近年は、いじめや自殺の深刻化を受けて、「生命の尊さ」の指導が自殺予防教育や生命（いのち）の教育と密接に関連付けて行われるようになっている。また医療技術の発展に伴う生命倫理上の課題（臓器移植、出生前診断など）を扱う教材も見られ、単に「命は大切だ」という価値の押し付けにとどまらず、生命をめぐる複雑な現実について多面的・多角的に考えさせる授業づくりが課題となっている。",
