    body: "「節度、節制」は、道徳科の内容項目における視点A「主として自分自身に関すること」に位置付けられる内容項目であり、自らの生活を振り返り、健康や安全に気を配りながら、行き過ぎた欲求や行動を自ら律して節度ある生活を送ろうとする態度を育てることを目標とする。学習指導要領解説では、基本的な生活習慣を身に付けることから始まり、学年が進むにつれて、自分の生活を振り返り節度をわきまえて節制に心掛けるという、より自律的な生活態度の形成へと発展していく構成が示されている。\n\n小学校低学年では、健康や安全に気を付け、物や金銭を大切にし、身の回りを整えるといった基本的な生活習慣の形成が中心となる。学年が上がるにつれて、快適な生活と健康、安全とのバランスを自分で考え、自分の生活を見直して節度を守るという、より主体的・自律的な側面が強調されるようになる。中学校段階では、望ましい生活習慣を身に付け、心身の健康の増進を図り、節度を守り節制に心掛けて安全で調和のある生活をするという、生涯にわたる生活態度の基盤として位置付けられる。\n\nこの内容項目は、生活習慣の確立や健康教育、安全教育とも密接に関わっており、スマートフォンやゲームなど情報機器の利用における自己統制の問題を扱う教材とも関連付けて指導されることが多い。単に「規則正しい生活をしましょう」という一方的な生活指導にとどまらず、なぜ節度・節制が自分自身や周囲の人々にとって大切なのかを児童生徒自身が考える授業展開が求められている。",
