    body: "「公正、公平、社会正義」は、道徳科の内容項目における視点C「主として集団や社会との関わりに関すること」に位置付けられる内容項目であり、誰に対しても差別や偏見のない公正・公平な態度で接し、正義を大切にして誰に対しても公正・公平に振る舞い、みんなが仲良く助け合う社会の実現に努める態度を育てることを目標とする。学習指導要領解説では、この内容項目がいじめの防止や多様性の尊重と特に深く関わるものとして位置付けられている。\n\n発達段階に応じて、小学校低学年では「自分の好き嫌いにとらわれないで接すること」という身近な公平さから始まり、学年が上がるにつれて、誰に対しても差別をすることや偏見を持つことなく、公正・公平な態度で人と接することへ、さらに中学校段階では正義を重んじ、誰に対しても公正・公平に接し、差別や偏見のない社会の実現に努めることへと、より社会的な視野を伴う内容に発展していく。\n\nこの内容項目は、2013年制定のいじめ防止対策推進法を背景として、道徳の教科化が議論される中で特に重視されるようになった経緯があり、いじめ防止教育の中核をなす内容項目の一つに位置付けられている。授業では、いじめの傍観者の心理や集団心理、差別・偏見の構造を扱う教材が多く用いられ、単に「いじめはいけない」という結論を教え込むのではなく、なぜいじめが生じるのか、公正・公平な集団をどう作るのかを児童生徒自身に考えさせる授業づくりが課題とされている。",
