    body: "「善悪の判断，自律，自由と責任」は、小学校の道徳科の内容項目のうち、視点A「主として自分自身に関すること」の最初に挙げられる項目です。低学年では「よいことと悪いこととの区別をし，よいと思うことを進んで行うこと」、中学年では正しいと判断したことを自信をもって行うこと、高学年では「自由を大切にし，自律的に判断し，責任のある行動をすること」と、学年段階に応じて発展していきます。中学校では「自主，自律，自由と責任」という名称で、自律の精神を重んじ、自主的に考え、判断し、誠実に実行してその結果に責任をもつことが示されています。\n\nこの項目の中心にあるのは、周囲の目や賞罰ではなく、自分の内なる基準によって行動を選ぶという意味での自律です。カントの自律の思想や、他律から自律へという道徳性発達の考え方とも結びつきます。授業では「自由」と「自分勝手」の違いを考えさせる主題がよく取り上げられ、自由には自分で判断する責任が伴うことに気づかせる展開が多く見られます。教材としては、国が作成した道徳教材『わたしたちの道徳』の「うばわれた自由」や、検定教科書の修学旅行を題材にした読み物などが使われてきました。\n\n指導上は、善悪の判断を単に「正解を教える」ものにしないことが大切です。「分かっていてもできない」という葛藤や、仲間との関係の中で正しいと思うことを貫く難しさを子ども自身が見つめ、道徳的価値の自覚を深める時間として設計することが求められます。他の項目と組み合わせながら、道徳的判断力・心情・実践意欲と態度を総合的に育てる中核の項目といえます。",
