    body: "「正直，誠実」は、小学校の道徳科で視点A「主として自分自身に関すること」に位置づけられる内容項目です。低学年では「うそをついたりごまかしをしたりしないで，素直に伸び伸びと生活すること」が示され、学年が上がるにつれて、過ちを素直に認めて改めること、誠実に明るい心で生活することへと発展します。中学校では独立した項目名としては立てられておらず、自主・自律の項目の中で「誠実に実行してその結果に責任をもつ」という形で関連づけられています。\n\nこの項目で重視されるのは、うそをつかないという行為の規範だけでなく、自分に対しても他者に対しても偽らず、心の中のうしろめたさを解消して「伸び伸びと」生活できるという実感です。そのため授業では、うそをついてしまった後の気持ちの変化や、正直に打ち明けることの勇気と相手の反応に注目する展開が多く用いられます。ただし、ときに正直さと思いやりが衝突する場面（相手を傷つける本当のことをどう伝えるか）もあり、親切・思いやりの項目と合わせて考える視点も重要です。\n\n指導にあたっては、「正直に言えばほめられる」といった賞罰による動機づけに偏らないよう注意が必要です。失敗やうそを責めすぎる学級では、かえって子どもが隠すようになることも指摘されています。安心して失敗を認められる学級の雰囲気づくりとあわせて、道徳科と特別活動・生徒指導を関連させた指導が求められます。",
