    body: "「個性の伸長」は、道徳科の内容項目のうち視点A「主として自分自身に関すること」に属する項目です。個性が道徳の内容項目として取り上げられるようになったのは平成元年（1989年）告示の学習指導要領からとされ、2017年告示の小学校学習指導要領では、低学年にも新たに加わりました。低学年では「自分の特徴に気付くこと」、中学年・高学年では自分の特徴に気づき、長所を伸ばすことへと進み、中学校では「向上心，個性の伸長」として、自己を見つめ、自己の向上を図るとともに、個性を伸ばして充実した生き方を追求することが示されています。\n\nこの項目で大切なのは、個性を「他人と違うこと」や「得意なことの発見」だけに矮小化しないことです。長所だけでなく短所も含めて自分を受け止め、それをどう生かすかを考えること、また他者の個性も尊重する姿勢につなげることが求められます。このため、相互理解・寛容や、自分を肯定的にとらえる自己有用感・自己効力感の育成とも深く関わります。\n\n指導上の留意点として、「自分には取り柄がない」と感じている子どもへの配慮があります。比較による優劣ではなく、周囲の人からの肯定的なフィードバックを通じて自分のよさに気づく活動が有効とされます。ポートフォリオ的な振り返りや、道徳ノートに自分の成長を記録する取り組みと組み合わせる実践も見られます。",
