    body: "「希望と勇気，努力と強い意志」は、道徳科の視点A「主として自分自身に関すること」に位置づけられる内容項目です。小学校中学年では「自分でやろうと決めた目標に向かって，強い意志をもち，粘り強くやり抜くこと」、高学年では「より高い目標を立て，希望と勇気をもち，困難があってもくじけずに努力して物事をやりぬくこと」と発展します。中学校では「希望と勇気，克己と強い意志」とされ、より高い目標を設定し、困難や失敗を乗り越えて着実にやり抜く意志が重視されます。\n\n発達上の背景として、高学年の児童は理想を追い求める一方で、夢と現実のずれを意識して自信をもちにくくなる時期にあたります。この項目は、目標設定の大切さだけでなく、失敗や挫折を経験したときにそれをどう受け止めるかを考える機会として機能します。スポーツ選手や芸術家など、困難を乗り越えた人物を扱う教材がよく用いられますが、「努力すれば必ず報われる」という単純な結論に陥らないよう、努力の過程で支えとなる周囲の人々や、目標の修正も含めて考えさせる工夫が必要です。\n\n心理学の概念では、成長への信念を扱うグロースマインドセットやレジリエンス、自己効力感と重なる部分が多い項目です。ただし道徳科では、成果の達成そのものではなく、困難に向き合う心の在り方を道徳的価値として自覚させる点に独自のねらいがあります。",
