    body: "「礼儀」は、道徳科の視点B「主として人との関わりに関すること」に位置づけられる内容項目で、小学校・中学校の双方に置かれています。低学年では気持ちのよいあいさつや言葉遣いといった身近な振る舞いから始まり、学年が上がるにつれて、相手の立場や状況を考えた適切な言動へと発展します。中学校では、礼儀の意義を理解し、時と場に応じた適切な言動をとることが求められます。\n\n礼儀は、単なる作法やマナーの暗記とは区別されます。形式を整えること自体が目的ではなく、相手を尊重し大切に思う心を、行為として表現する点に本質があるとされます。したがって、同じ「あいさつ」でも、時と場、相手との関係によって適切な形は異なります。授業では、形だけ整っているが心がこもっていない場面と、形は不十分でも真心が伝わる場面を比較させるなど、形と心の関係を問い直す展開が用いられます。\n\n指導上の留意点として、礼儀作法を一方的に押しつける指導に陥らないことが挙げられます。礼儀は文化や社会によって形が異なる面があり、日本の伝統的な作法を学ぶことは、伝統と文化の尊重や国際理解の項目とも関連づけられます。また、日常のあいさつ指導は生徒指導や特別活動でも行われるため、道徳科では行為の背景にある心を考えることに重点を置くのが望ましいとされます。",
