    body: "「友情，信頼」は、道徳科の視点B「主として人との関わりに関すること」の内容項目です。小学校では、低学年の「友達と仲よくし，助け合うこと」、中学年の互いに理解し信頼して助け合うこと、高学年の「友達と互いに信頼し，学び合って友情を深め，異性についても理解しながら，人間関係を築いていくこと」と段階的に発展します。中学校では、友情の尊さを理解して心から信頼できる友達をもち、互いに励まし合い、高め合うことが中心に置かれています。\n\n発達段階の特徴として、中学生になると互いに心を許し合える友達を真剣に求めるようになる一方で、相手に合わせすぎたり、逆に距離を置いたりする傾向も指摘されます。そのため授業では、仲がよいことと、時に相手のために厳しいことを言える関係との違いを考える展開がしばしば取り入れられます。また、友情の名のもとに同調圧力が生じたり、いじめの背景になったりすることがあるため、集団の中での友情のあり方を考えさせる視点も重要です。\n\n生徒指導との関連では、友人関係のトラブルが学校生活に及ぼす影響が大きいことから、道徳科で友情の価値を考えることが、ピアサポートや仲間づくりの活動の土台にもなります。ただし道徳科は問題が起きた後の対処のための時間ではなく、価値についての理解を深める時間であるという点は区別して扱う必要があります。",
