    body: "道徳科の視点C「主として集団や社会との関わりに関すること」には、きまりや法に関する項目が置かれています。小学校では「規則の尊重」として、約束や社会のきまりの意義を理解し、それらを守ることが扱われ、中学校では視点Cの最初の項目として「遵法精神，公徳心」が示されます。中学校では、法やきまりの意義を理解したうえで進んで守るだけでなく、それらを守ることを通して秩序と規律ある社会の実現に努めること、権利を主張するだけでなく義務を果たすことが重視されます。\n\nこの項目の授業では、「きまりは何のためにあるのか」「権利と義務の関係はどうあるべきか」といった主題がよく設定されます。きまりを「守らされるもの」ではなく、みんなが気持ちよく生活するために必要なものとして捉え直すことが重要です。一方で、きまりそのものが不合理であった場合にどうするかを考える視点も、法やルールを批判的に吟味する態度を育てるうえで意味をもちます。\n\n関連する教育活動として、法務省が推進する法教育や、学校のきまりを生徒自身が見直す活動（ブラック校則をめぐる議論を含む）があります。道徳科ではこうした活動と連携しつつ、きまりを守る行為の背景にある価値を考える時間として位置づけることが求められます。規範意識の育成という観点では、公共の精神や公正・公平の項目とあわせて扱われます。",
