    body: "「国際理解，国際親善」は、道徳科の視点C「主として集団や社会との関わりに関すること」に属する内容項目です。小学校では、低学年の「他国の人々や文化に親しむこと」、中学年の他国の人々や文化に親しみ関心をもつこと、高学年の他国の人々や文化について理解し、日本人としての自覚をもって国際親善に努めることへと発展します。2017年告示の学習指導要領では、低学年にもこの項目が位置づけられました。中学校では「国際理解，国際貢献」として、世界の中の日本人としての自覚をもち、国際的視野に立って世界の平和と人類の発展に寄与する内容が示されています。\n\nこの項目は、自国の伝統と文化を尊重し国や郷土を愛する態度とセットで扱われる点に特徴があります。自国への理解と愛情を基盤として他国を理解するという構成であり、授業では、国境を越えて互いを尊重し助け合う姿を描いた教材（例えば、海外の人々との交流を扱った読み物）が用いられます。\n\n注意点として、国際理解は他国の文化を「珍しいもの」として消費する態度に陥りやすいことが挙げられます。日本社会に暮らす外国にルーツをもつ子どもが増える中で、国際理解は身近な多様性の尊重とも結びつけて考える必要があります。この点で、多文化共生教育や、国際理解教育、持続可能な開発のための教育（ESD）とも関連が深い項目です。",
