    body: "道徳科の視点D「主として生命や自然，崇高なものとの関わりに関すること」には、「生命の尊さ」「自然愛護」「感動，畏敬の念」「よりよく生きる喜び」の項目が置かれています。このうち「自然愛護」は、自然の美しさや崇高さを知り、自然環境を大切にする態度を扱います。「感動，畏敬の念」は、美しいものや気高いものに感動する心と、人間の力を超えたものに対する畏敬の念をもつことを扱います。2017年告示の学習指導要領では、中学校においても両者が別々の内容項目として整理されています。\n\n畏敬の念は、特定の宗教的な意味での信仰を求めるものではなく、人間の力を超えた大自然や崇高なものを前にして謙虚になる心を指します。ここには、宗教的情操の教育に関する議論とも重なる部分がありますが、公立学校では特定の宗派に偏らない形で扱われます。また、自然だけでなく、人の生き方や芸術、人間の気高さの中にも感動や畏敬の対象があると捉える考え方が示されています。\n\n実践では、美しさが目に見える物だけでなく、人の心や行為の中にもあることに気づかせる授業や、中学校で雄大な自然景観を題材に人間と自然との関わりを多面的に考える授業が行われています。環境教育やESDとの接点が大きい一方、道徳科では環境保全の知識の習得そのものではなく、自然に対する心の在り方を扱う点に区別があります。",
