    body: "「家族愛，家庭生活の充実」は、道徳科の視点C「主として集団や社会との関わりに関すること」に属する内容項目です。小学校の高学年では、父母、祖父母を敬愛し、家族の一員としての自覚をもって充実した家庭生活を築くことが示されています。解説では、自分が今ここにいるのは、祖父母や父母がかけがえのない存在として深い愛情をもって育ててくれたからであると気づかせることが大切とされています。中学校では、自立心が高まり家族に反抗的になりやすい時期であることを踏まえ、家族の一員としての役割や責任を考えることが求められます。\n\n教科書では、母親、父親、兄弟姉妹、祖父母などが登場する題材が多く、家族のあたたかさを描くものが中心です。しかし、現代の子どもたちの家庭状況は、ひとり親家庭、再婚家庭、里親や施設で暮らす子ども、ヤングケアラー、外国にルーツをもつ家庭、虐待の経験をもつ子どもなど、一様ではありません。学習指導要領の解説も、家庭の状況が一様でないことを踏まえて、一人一人の児童生徒の実態の把握と十分な配慮を求めています。\n\n指導では、理想的な家族像を押しつけるのではなく、家庭のかたちが異なっても、自分を支えてくれる人への感謝や、互いに思いやる関係の大切さを考えられるよう配慮します。また、家庭に問題を抱える子どもの発言が出た場合には、授業後の個別対応につなげるなど、生徒指導や教育相談と連携した慎重な対応が必要です。",
