    summary:
      "大津市のいじめ問題を契機に、教育再生実行会議の提言、中教審答申を経て、2015年に「特別の教科 道徳」が設けられるまでの経緯。",
    body: "「道徳の時間」を教科に格上げする議論は戦後たびたび行われてきましたが、直接の契機となったのは大津市で起きた中学生のいじめ自殺事件を受けた、いじめ問題への対応でした。2013年2月、政府の教育再生実行会議が第1次提言『いじめ問題等への対応について』を取りまとめ、道徳の教科化を打ち出しました。同年12月には、文部科学省の「道徳教育の充実に関する懇談会」が報告書を提出し、検定教科書の導入などが盛り込まれました。\n\n2014年10月21日には中央教育審議会が答申を行い、「道徳の時間」を「特別の教科 道徳」として位置づけること、検定教科書を導入すること、評価は数値ではなく記述式とすることなどが示されました。これを受けて、2015年3月27日に学習指導要領が一部改正され、道徳科が成立しました。全面実施は、小学校が2018（平成30）年度、中学校が2019（平成31）年度からです。\n\n教科化をめぐっては、いじめ対策として道徳の教科化が有効なのかという疑問や、内心に関わる道徳の評価や検定教科書による国家の関与への批判など、賛否が分かれています。一方、従来の道徳の時間が「読み物の登場人物の心情理解に偏りがちである」と批判されてきたことへの改善策として、「考え、議論する道徳」への質的転換が目指されました。経緯の評価は立場により分かれるため、複数の資料にあたって理解することが大切です。",
