    body: "道徳の教科化によって、道徳科では、他の教科と同様に文部科学大臣の検定を経た教科書を使用することになりました。小学校では2018（平成30）年度、中学校では2019（平成31）年度から検定教科書による授業が始まっています。それ以前の道徳の時間では、教科書は存在せず、副読本や国が作成した『心のノート』『私たちの道徳』、地域の教材などが使われていました。\n\n最初の小学校用教科書の検定では、検定意見が付いたことが報じられ、郷土愛が足りないとして「パン屋」が「和菓子屋」に改められた例などが議論を呼びました。このことから、検定が特定の価値観を誘導するのではないかという批判と、教科書の質を確保する制度であるという見方が対立しました。実際の授業では、教科書教材のみを使用する教員もいれば、地域の素材や時事的な題材を補う教員もおり、教材開発のあり方は学校によって異なります。\n\n教科書の内容は、学習指導要領に示された内容項目を全学年で網羅する構成になっており、読み物教材が中心です。検定教科書の使用義務がある一方で、教科書の内容を教えることが目的ではなく、教科書を材料として道徳的価値を考える点にこの教科の特質があります。採択は教科書無償措置法に基づき、教育委員会が行います。",
