    summary:
      "法律の専門家ではない一般の人が、法や司法制度とその基礎にある価値を理解し、法的なものの考え方を身につけるための教育。",
    body: "法教育は、法務省の整理によれば、法律専門家ではない一般の人々が、法や司法制度、これらの基礎になっている価値を理解し、法的なものの考え方を身につけるための教育です。アメリカのロー・リレイテッド・エデュケーション（Law-Related Education）に由来するとされ、法の条文や制度を暗記させる知識型の教育ではなく、法やルールの背景にある価値観、司法制度の機能や意義を考える思考型の教育であることが特徴とされています。\n\n日本では、司法制度改革審議会の意見書が学校教育における司法に関する学習機会の充実を求めたことを受け、2003年7月に法務省が法教育研究会を発足させました。研究会は2004年11月に報告書をまとめ、中学3年生を対象としたルールづくり、私法と消費者保護、憲法の意義、司法の役割という4つの教材例を作成しています。その後、学習指導要領でも社会科・公民科を中心に法に関する学習が充実され、2022年度から実施の高等学校の「公共」でも関連する内容が扱われています。\n\n法教育は社会科だけでなく、道徳科や特別活動でも展開が可能とされます。道徳科では「規則の尊重」「遵法精神，公徳心」「公正，公平，社会正義」などの項目と関連し、ルールの意義を子ども自身が考える活動に結びつけられます。民主主義社会の形成者としての主権者教育の基礎に位置づく教育でもあります。",
