    body: "同和教育は、同和問題（部落差別）の解決を目的とする教育実践の総称で、戦後の部落解放運動や教師たちの取り組みの中で形づくられてきました。1965（昭和40）年の同和対策審議会答申は、同和問題の早急な解決は国の責務であり国民的課題であると示し、1969年の同和対策事業特別措置法をはじめとする特別措置法に基づく対策事業が、2002（平成14）年3月まで進められました。学校教育では、教職員の資質向上、教材整備、カリキュラム開発、進路保障などが課題とされ、社会教育でも学級・講座での学習が行われました。\n\n特別措置法の終了後は、一般対策の中で部落差別の解消に取り組むことになり、2000年に施行された人権教育及び人権啓発の推進に関する法律のもとで、同和教育の成果を受け継いだ人権教育が推進されました。さらに2016（平成28）年には部落差別の解消の推進に関する法律（部落差別解消推進法）が公布・施行されています。近年の部落問題学習は、歴史的な事実や差別の構造を学ぶことに加え、インターネット上の差別的な書き込みなど現代の課題を扱う必要も指摘されています。\n\n道徳科の観点では、「公正，公平，社会正義」の項目が関連づけられ、偏見や差別を許さない態度を育てる授業が行われます。ただし、差別の当事者が教室にいる可能性への配慮や、無自覚に差別を再生産しない教材選びなど、指導には慎重さが求められます。人権教育の個別的な視点の一つとして、他の人権課題（外国人、障害者、性的少数者など）の学習と関連づけて進められます。",
