      "死について学び考えることを通して、よりよく生きることを目指す教育。アルフォンス・デーケンが「死への準備教育」と訳して日本に紹介した。",
    body: "デス・エデュケーション（death education）は、直訳すれば「死の教育」ですが、日本では、上智大学の教授であったアルフォンス・デーケン（1932〜2020）が「死への準備教育」と訳して紹介し、日本における死生学の先駆けとなりました。死ぬ瞬間まで生きている人間が、残された時間をどう生きるかを考える教育という意味合いが込められています。デーケンは上智大学の哲学の授業でこの教育を行い、1982年に市民向けの「生と死を考えるセミナー」を開催しました。これが翌年の「生と死を考える会」の結成につながり、1986年には叢書『死への準備教育』も刊行されています。\n\nデス・エデュケーションの目的は、死を避けるべきタブーとして遠ざけるのではなく、死への理解を深めることで、自分や他者の生命を大切にし、限りある生を主体的に生きる態度を養うことにあります。内容としては、死の概念や死別の悲しみ（グリーフ）、終末期医療、遺される人へのケアなどが扱われます。学校教育では、いのちの教育や生命尊重の教育の一環として、ペットや身近な人の死、病気や災害を題材とした実践が行われています。\n\n指導にあたっては、家族を亡くした子どもへの配慮が不可欠です。授業が当事者の心に強い負担を与えうることを想定し、事前の情報共有や、授業後のフォロー、スクールカウンセラーとの連携が重要になります。道徳科の「生命の尊さ」や「よりよく生きる喜び」の項目とも関連が深い領域です。",
