    body: "価値葛藤場面の設定は、コールバーグの道徳性発達理論や討議倫理学の知見を背景に、単一の徳目を教え込む注入型の指導から脱却するために重視されてきた。善悪の二者択一ではなく、友情と公正、自己犠牲と規則遵守など、正義や誠実さが衝突する状況を扱う。\n\n授業実践では、登場人物が岐路に立つ場面を資料から抽出し、どちらの立場を選択すべきかを学級全体で議論させる。児童生徒は互いの理由付けの違いに触れ、他者の立場から物事を捉え直すことで、自らの道徳的判断の根拠を批判的に検討する。\n\n多様で複雑な現代社会では、単純な正解が存在しない課題に向き合う機会が多い。価値葛藤を通じた対話は、児童生徒に深い思索と他者理解をもたらし、自律的な判断力とよりよい生き方を追求する姿勢を育成する基盤となる。",
