    body: "自己の生命が無数の先祖や先人の努力、自然の恵みの連鎖によって支えられて現在にあるという命の有限性と連続性を実感させる道徳教育の指導領域である。日本の伝統的な精神文化に根ざす報恩感謝の念や先人への敬慕の心を、現代的な生命尊重の倫理的価値へと結びつけている。\n\n授業では、親や祖父母の温かな愛情、家族や地域の歩んできた歴史、苦難を乗り越えて生命をつないだ人々の物語を教材として活用する。自らの生命が多くの人々の支えと恩恵の上に成立している事実に気づかせ、身近な家族や先人への素直な感謝の念を言葉にして表現させる対話を行う。\n\n生命を自他ともに不可侵の尊い存在として捉え直すことで、自暴自棄を戒めるとともに、次世代への責任を自覚して命を慈しみ力強く生き抜く豊かな人間性と確固たる道徳的信条を培う。",
